function inMonth(d,m){return monthKey(d)===m}function txExpenses(m,basis='cash'){return state.transactions.filter(t=>t.type==='expense').flatMap(t=>{if(t.cardId){if(basis==='competence')return monthKey(t.purchaseDate)===m?[{...t,amount:+t.amount,when:t.purchaseDate}]:[];return installments(t).filter(x=>monthKey(x.due)===m).map(x=>({...t,amount:x.amount,when:x.due}))}if(t.recurring){const first=monthKey(t.purchaseDate);if(m<first)return[];if(t.recurringEnd&&m>monthKey(t.recurringEnd))return[];return[{...t,amount:+t.amount,when:dateInMonth(m,t.day||Number(t.paymentDate.slice(-2)))}]}return [t].filter(x=>inMonth(basis==='cash'?x.paymentDate:x.purchaseDate,m))})}function txIncome(m){return state.transactions.filter(t=>t.type==='income').filter(t=>t.recurring?(m>=monthKey(t.paymentDate)&&(!t.recurringEnd||m<=monthKey(t.recurringEnd))):inMonth(t.paymentDate,m))}function txInvest(m){return state.transactions.filter(t=>t.type==='investment'&&inMonth(t.paymentDate,m))}function installments(t){const count=Math.max(1,Number(t.installments)||1),out=[],v=Math.round(+t.amount*100);const base=Math.floor(v/count),remainder=v-base*count,first=monthKey(t.firstDue||t.paymentDate||t.purchaseDate);for(let i=0;i<count;i++){const mo=addMonths(first,i);out.push({due:dateInMonth(mo,t.dueDay||Number((t.firstDue||t.paymentDate||t.purchaseDate).slice(-2))),amount:(base+(i<remainder?1:0))/100,num:i+1})}return out}function sums(m){const ins=txIncome(m).reduce((a,t)=>a+ +t.amount,0),expenses=txExpenses(m).reduce((a,t)=>a+ +t.amount,0),invest=txInvest(m).reduce((a,t)=>a+(t.operation==='resgate'?-1:1)* +t.amount,0);return{ins,expenses,invest,left:ins-expenses-invest}}

